int main(){
    int n,k;
    scanf("%d %d",&n,&k);
    // Lyndon words of length 1 and 2 in lex order: i, then (i,j) for j>i
    string w;
    for(int i=0;i<k;i++){
        w.push_back('a'+i);
        for(int j=i+1;j<k;j++){ w.push_back('a'+i); w.push_back('a'+j); }
    }
    string s;
    s.reserve(n);
    for(int i=0;i<n;i++) s.push_back(w[i % w.size()]);
    puts(s.c_str());
}

