int main(){
    int t; scanf("%d",&t);
    while(t--){
        long long n,m,k; scanf("%lld %lld %lld",&n,&m,&k);
        bool swp = m > n;                       // make '0' the majority char
        long long A = swp ? m : n, B = swp ? n : m;
        long long d = A - B;
        if(k < d || k > A){ puts("-1"); continue; }
        string s(k, '0');                       // 0^k
        for(long long i=0;i<A-k;i++) s += "10"; // (10)^(A-k)
        s.append(B-(A-k), '1');                 // remaining ones
        if(swp) for(char &c: s) c = (c=='0') ? '1' : '0';
        puts(s.c_str());
    }
}

