        int n,m; scanf("%d %d",&n,&m);
        vector<int> a(n), b(n), c(m);
        for(auto&x:a) scanf("%d",&x);
        for(auto&x:b) scanf("%d",&x);
        for(auto&x:c) scanf("%d",&x);
        int cm = c[m-1];
        // choose plank p with b_p = cm, preferring one that needs repainting
        int p=-1;
        for(int i=0;i<n;i++) if(b[i]==cm && a[i]!=b[i]){ p=i; break; }
        if(p<0) for(int i=0;i<n;i++) if(b[i]==cm){ p=i; break; }
        if(p<0){ puts("NO"); continue; }
        vector<vector<int>> need_list(n+1), painters(n+1);
        for(int i=0;i<n;i++) if(a[i]!=b[i] && i!=p) need_list[b[i]].push_back(i);
        for(int j=0;j<m-1;j++) painters[c[j]].push_back(j);
        bool ok=true;
        for(int col=1;col<=n;col++) if(need_list[col].size()>painters[col].size()){ ok=false; break; }
        if(!ok){ puts("NO"); continue; }
        vector<int> x(m, p+1);
        for(int col=1;col<=n;col++)
            for(size_t k=0;k<need_list[col].size();k++)
                x[painters[col][k]] = need_list[col][k]+1;
        puts("YES");
        for(int j=0;j<m;j++) printf("%d%c", x[j], j+1<m?' ':'\n');
    }
}

