        for(auto&x:a) scanf("%lld",&x);
        for(auto&x:b) scanf("%lld",&x);
        sort(a.begin(),a.end());
        sort(b.begin(),b.end());
        vector<long long> cand(a);
        cand.insert(cand.end(), b.begin(), b.end());
        sort(cand.begin(),cand.end());
        long long best=0;
        for(long long p: cand){
            long long buyers = n - (lower_bound(b.begin(),b.end(),p) - b.begin());   // b_i >= p
            long long pos = n - (lower_bound(a.begin(),a.end(),p) - a.begin());      // a_i >= p
