int main(){
    const int LIM = 31623;
    vector<int> primes;
    {
        vector<bool> comp(LIM+1,false);
        for(int i=2;i<=LIM;i++){
            if(!comp[i]){ primes.push_back(i); for(long long j=(long long)i*i;j<=LIM;j+=i) comp[j]=true; }
        }
    }
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n);
        for(auto&x:a) scanf("%lld",&x);
        set<long long> seen;
        bool ok=false;
        for(long long x: a){
            for(int p: primes){
                if((long long)p*p > x) break;
                if(x%p==0){
                    if(seen.count(p)) ok=true;
                    seen.insert(p);
                    while(x%p==0) x/=p;
                }
            }
            if(x>1){
                if(seen.count(x)) ok=true;
                seen.insert(x);
            }
            if(ok) break;
        }
        puts(ok?"YES":"NO");
    }
}

