        long long h,w,xa,ya,xb,yb;
        scanf("%lld %lld %lld %lld %lld %lld",&h,&w,&xa,&ya,&xb,&yb);
        if(xa>=xb){ puts("Draw"); continue; }
        long long dx=xb-xa, dy=llabs(ya-yb), Lb, La;
        if(yb>ya){ Lb=w-yb; La=ya-1; }
        else if(yb<ya){ Lb=yb-1; La=w-ya; }
        else { Lb=max(w-yb,yb-1); La=max(ya-1,w-ya); }
        if(dx%2==1){
            long long R=(dx-1)/2;
            puts(dy-R+min(R,Lb)<=1 ? "Alice" : "Draw");
        } else {
            long long RB=dx/2-1;
            puts(dy-RB+min(RB+1,La)<=1 ? "Bob" : "Draw");
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,l,r; long long s; scanf("%d %d %d %lld",&n,&l,&r,&s);
        int len=r-l+1;
        long long mn=(long long)len*(len+1)/2;
        long long mx=0; for(int i=0;i<len;i++) mx+=n-i;
        if(s<mn||s>mx){ puts("-1"); continue; }
        // pick len distinct values in [1,n] summing to s, starting from {1..len}
        vector<long long> c(len);
        for(int i=0;i<len;i++) c[i]=i+1;
        long long need=s-mn;
        for(int i=len-1;i>=0 && need>0;i--){
            long long cap = n-(len-1-i);       // largest value this slot can take
            long long inc = min(need, cap-c[i]);
            c[i]+=inc; need-=inc;
        }
        vector<bool> used(n+1,false);
        for(auto v:c) used[v]=true;
        vector<int> rest;
        for(int v=1;v<=n;v++) if(!used[v]) rest.push_back(v);
        vector<int> p(n+1,0);
        for(int i=0;i<len;i++) p[l+i]=c[i];
        size_t q=0;
        for(int i=1;i<=n;i++) if(i<l||i>r) p[i]=rest[q++];
        for(int i=1;i<=n;i++) printf("%d%c", p[i], i<n?' ':'\n');
    }
}

