int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n);
        for(auto&x:a) scanf("%lld",&x);
        vector<bool> chain(n,false);
        long long sufmin=LLONG_MAX;
        for(int i=n-1;i>=0;i--){
            if(a[i]<=sufmin) chain[i]=true;   // suffix minimum (non-strict)
            sufmin=min(sufmin,a[i]);
        }
        long long minN=LLONG_MAX;
        for(int i=0;i<n;i++) if(!chain[i]) minN=min(minN,a[i]);
        long long thr = (minN==LLONG_MAX) ? LLONG_MAX : minN+1;
        vector<long long> res, tail;
        vector<bool> kept(n,false);
        for(int i=0;i<n;i++) if(chain[i] && a[i]<=thr){ kept[i]=true; res.push_back(a[i]); }
        for(int i=0;i<n;i++) if(!kept[i]) tail.push_back(a[i]+1);
        sort(tail.begin(),tail.end());
        for(auto v:tail) res.push_back(v);
        for(size_t i=0;i<res.size();i++) printf("%lld%c", res[i], i+1<res.size()?' ':'\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    static char buf[200005];
    while(t--){
        scanf("%s",buf);
        int n=strlen(buf);
        vector<long long> P0(n+1,0), P1(n+1,0);
        for(int i=0;i<n;i++){
            P0[i+1]=P0[i]+(buf[i]=='0');
            P1[i+1]=P1[i]+(buf[i]=='1');
        }
        long long O=P1[n];
        // kept substring = [l, r), cost = max(zeros kept, ones removed)
        auto zeros=[&](int l,int r){ return P0[r]-P0[l]; };
        auto outs =[&](int l,int r){ return O-(P1[r]-P1[l]); };
        long long best=O;   // keep nothing: remove all ones, cost = O
        for(int l=0;l<=n;l++){
            // smallest r in [l,n] with zeros >= ones_removed (monotone in r)
            int lo=l, hi=n+1;
            while(lo<hi){
                int mid=(lo+hi)/2;
                if(zeros(l,mid)>=outs(l,mid)) hi=mid; else lo=mid+1;
            }
            if(lo<=n) best=min(best,max(zeros(l,lo),outs(l,lo)));
            if(lo-1>=l) best=min(best,max(zeros(l,lo-1),outs(l,lo-1)));
        }
        printf("%lld\n",best);
    }
}

