int main(){
    int T; scanf("%d",&T);
    static char buf[100005];
    while(T--){
        int n; scanf("%d %s",&n,buf);
        string s(buf);
        int cnt[26]={0};
        for(char ch: s) cnt[ch-'a']++;
        int bestMatch=-1, bestD=1; vector<int> bestSet;
        for(int d=1; d<=26; d++){
            if(n%d) continue;
            int c=n/d;
            vector<pair<int,int>> v;                    // (min(cnt, c), letter)
            for(int l=0;l<26;l++) v.push_back({min(cnt[l],c), l});
            sort(v.rbegin(), v.rend());
            int match=0; vector<int> set_;
            for(int i=0;i<d;i++){ match+=v[i].first; set_.push_back(v[i].second); }
            if(match>bestMatch){ bestMatch=match; bestD=d; bestSet=set_; }
        }
        int c=n/bestD;
        vector<bool> chosen(26,false);
        for(int l: bestSet) chosen[l]=true;
        vector<int> kept(26,0), freePos;
        string t(n,'?');
        for(int i=0;i<n;i++){
            int l=s[i]-'a';
            if(chosen[l] && kept[l]<c){ kept[l]++; t[i]=s[i]; }
            else freePos.push_back(i);
        }
        size_t q=0;
        for(int l: bestSet)
            for(int need=c-kept[l]; need>0; need--) t[freePos[q++]]='a'+l;
        printf("%d\n%s\n", n-bestMatch, t.c_str());
    }
}

