    int T; scanf("%d",&T);
    while(T--){
        int n; long long k; scanf("%d %lld",&n,&k);
        // there are 2^(n-1) optimal permutations; k-th in lex order via bits of k-1
        if(n-1<62 && k > (1LL<<(n-1))){ puts("-1"); continue; }
        long long x=k-1;
        vector<int> p(n+1,0);
        int lo=1, hi=n;
        for(int v=1; v<=n-1; v++){
            int sh=(n-1)-v;
            int bit = (sh<62) ? (int)((x>>sh)&1) : 0;
            if(bit==0) p[lo++]=v; else p[hi--]=v;
        }
        p[lo]=n;
        for(int i=1;i<=n;i++) printf("%d%c", p[i], i<n?' ':'\n');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; long long k; scanf("%d %lld",&n,&k);
        vector<long long> a(n);
        for(auto&x:a) scanf("%lld",&x);
        // +1 if a_i <= k else -1; a segment is "good" (median <= k) iff its sum >= 0
        vector<long long> S(n+1,0);
        for(int i=0;i<n;i++) S[i+1]=S[i]+(a[i]<=k?1:-1);
        // cuts: 1 <= l < r <= n-1; need two of the three segments good
        // mxS[i] / mnS[i] = max / min of S over indices [i, n-1]
        vector<long long> mxS(n+1, LLONG_MIN), mnS(n+1, LLONG_MAX);
        for(int i=n-1;i>=1;i--){ mxS[i]=max(mxS[i+1],S[i]); mnS[i]=min(mnS[i+1],S[i]); }
        long long Sn=S[n];
        bool ok=false;
        // prefix+middle: S_l>=0 and some r in (l,n-1] with S_r>=S_l
        // prefix+suffix: S_l>=0 and some r in (l,n-1] with S_r<=S_n
        // middle+suffix: S_l<=S_r<=S_n for some l<r
        for(int l=1; l<=n-2 && !ok; l++){
            if(S[l]<0) continue;
            if(mxS[l+1]>=S[l]) ok=true;
            else if(mnS[l+1]<=Sn) ok=true;
        }
        if(!ok){
            long long pmin=LLONG_MAX;
            for(int r=2;r<=n-1;r++){
                pmin=min(pmin,S[r-1]);
                if(S[r]<=Sn && pmin<=S[r]){ ok=true; break; }
            }
        }
        puts(ok?"YES":"NO");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    priority_queue<long long, vector<long long>, greater<long long>> pq;
    vector<string> out;
    char op[16];
    for(int i=0;i<n;i++){
        scanf("%s",op);
        if(op[0]=='i'){           // insert x
            long long x; scanf("%lld",&x);
            pq.push(x);
            out.push_back("insert "+to_string(x));
        } else if(op[0]=='r'){   // removeMin
            if(pq.empty()){ out.push_back("insert 1"); pq.push(1); }
            pq.pop();
            out.push_back("removeMin");
        } else {                  // getMin x
            long long x; scanf("%lld",&x);
            while(!pq.empty() && pq.top()<x){ pq.pop(); out.push_back("removeMin"); }
            if(pq.empty() || pq.top()>x){ pq.push(x); out.push_back("insert "+to_string(x)); }
            out.push_back("getMin "+to_string(x));
        }
    }
    printf("%zu\n", out.size());
    for(auto&s:out) printf("%s\n", s.c_str());
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<long long> a(n);
    for(auto&x:a) scanf("%lld",&x);
    int m; scanf("%d",&m);
    vector<long long> b(m);
    for(auto&x:b) scanf("%lld",&x);
    long long sa=0, sb=0;
    for(auto x:a) sa+=x;
    for(auto x:b) sb+=x;
    if(sa!=sb){ puts("-1"); return 0; }
    // all values positive: common prefix sums give the maximum common length
    int i=0, j=0, cnt=0;
    long long pa=0, pb=0;
    // walk both arrays, advancing whichever prefix is smaller
    pa=a[0]; pb=b[0]; i=1; j=1;
    while(true){
        if(pa==pb){ cnt++; if(i==n && j==m) break; pa+=a[i++]; pb+=b[j++]; }
        else if(pa<pb){ pa+=a[i++]; }
        else { pb+=b[j++]; }
    }
    printf("%d\n", cnt);
}

