int main(){
    int n; scanf("%d",&n);
    static char buf[205]; scanf("%s",buf);
    string s(buf);
    int removed=0;
    // remove letter c while it touches c-1, from 'z' down to 'b'
    for(char c='z'; c>='b'; c--){
        bool changed=true;
        while(changed){
            changed=false;
            for(size_t i=0;i<s.size();i++){
                if(s[i]!=c) continue;
                bool adj = (i>0 && s[i-1]==c-1) || (i+1<s.size() && s[i+1]==c-1);
                if(adj){ s.erase(i,1); removed++; changed=true; break; }
            }
        }
    }
    printf("%d\n", removed);
}

#include <bits/stdc++.h>
using namespace std;
const long long MOD=998244353;
int main(){
    int n; scanf("%d",&n);
    vector<long long> a(n), b(n);
    for(auto&x:a) scanf("%lld",&x);
    for(auto&x:b) scanf("%lld",&x);
    // total = sum_i a_i * b_i * i * (n-i+1); weight w_i = i*(n-i+1); permute b freely
    vector<long long> x(n);
    for(int i=0;i<n;i++){
        long long w=(long long)(i+1)*(n-i);
        x[i]=a[i]*w;                       // fits in 64-bit: <= 1e6 * 1e10
    }
    sort(x.begin(),x.end());               // smallest weight gets largest b (rearrangement)
    sort(b.begin(),b.end(),greater<long long>());
    long long ans=0;
    for(int i=0;i<n;i++) ans=(ans + (x[i]%MOD)*(b[i]%MOD))%MOD;
    printf("%lld\n", ans);
}

