            day[idx]=dd;
            dq.push_back({x, dd});
        } else {
            days++;
            day[idx]=days;
            dq.push_back({x, days});
        }
    }
    printf("%d\n", days);
    for(int i=0;i<n;i++) printf("%d%c", day[i], i+1<n?' ':'\n');
