#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    static char buf[200005];
    while(t--){
        int n,k; scanf("%d %d",&n,&k);
        scanf("%s",buf);
        string s(buf);
        vector<int> L(k), R(k);
        for(auto&x:L) scanf("%d",&x);
        for(auto&x:R) scanf("%d",&x);
        int q; scanf("%d",&q);
        vector<vector<int>> cnt(k);
        for(int i=0;i<k;i++) cnt[i].assign((R[i]-L[i]+1)/2+2, 0);
        vector<int> seg(n+2,0);
        for(int i=0;i<k;i++) for(int p=L[i];p<=R[i];p++) seg[p]=i;
        for(int j=0;j<q;j++){
            int x; scanf("%d",&x);
            int i=seg[x];
            int d=min(x-L[i], R[i]-x);   // layer of the reversal start
            cnt[i][d]++;
        }
        // layer t (pair L+t, R-t) is reversed once per query with d <= t
        for(int i=0;i<k;i++){
            int l=L[i], r=R[i];
            int run=0;
            for(int tt=0; l+tt < r-tt; tt++){
                run += cnt[i][tt];
                if(run&1) swap(s[l+tt-1], s[r-tt-1]);
            }
        }
        puts(s.c_str());
    }
}

