    vector<int> col(n+1,0), par(n+1,0);
    col[1]=1;
    queue<int> q; q.push(1);
    vector<bool> vis(n+1,false); vis[1]=true;
    while(!q.empty()){
        int v=q.front(); q.pop();
        int c=1;
        for(int u: g[v]){
            if(vis[u]) continue;
            vis[u]=true;
            // pick next color not equal to col[v] and not equal to col[parent of v]
            while(c==col[v] || c==col[par[v]]) c++;
            col[u]=c++;
            par[u]=v;
            q.push(u);
        }
    }
    printf("%d\n", K);
    for(int v=1; v<=n; v++) printf("%d%c", col[v], v<n?' ':'\n');
}
